% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"source PDF page 37 question 8a; teacher PDF page 78 figure 8a"}
\begin{tikzpicture}[x=1cm,y=0.8cm]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-0.8,-3.4) rectangle (5.8,5.7);
\draw[black,line width=0.5pt,->] (-0.35,0)--(5.4,0) node[right] {$x$};
\draw[black,line width=0.5pt,->] (0,-3.2)--(0,3.7) node[above] {$y$};
\begin{scope}
\clip (0.015,-3.1) rectangle (5.1,3.5);
\draw[black,line width=0.8pt,<->] plot[domain=0.12:5,samples=160] (\x,{ln(\x)/ln(2)});
\draw[black,line width=0.8pt,dashed,<->] plot[domain=0.06:5,samples=160] (\x,{ln(\x)/ln(2)+1});
\draw[black,line width=0.8pt,dash dot,<->] plot[domain=0.24:5,samples=160] (\x,{ln(\x)/ln(2)-1});
\end{scope}
\foreach \x/\t in {0.5/{\frac12},1/1,2/2,4/4}{\draw[black,line width=0.4pt] (\x,0.06)--(\x,-0.06);\node[below] at (\x,-0.08) {\special{dvisvgm:raw <g data-graph-text="tick">}$\t$\special{dvisvgm:raw </g>}};}
\foreach \y in {-2,-1,1,2,3}{\draw[black,line width=0.4pt] (-0.06,\y)--(0.06,\y);\node[left] at (-0.07,\y) {\special{dvisvgm:raw <g data-graph-text="tick">}$\y$\special{dvisvgm:raw </g>}};}
\fill[black] (0.5,0) circle (1.1pt) (1,0) circle (1.1pt) (2,0) circle (1.1pt);
\node[anchor=west] at (0,5.35) {Asymptote: $x=0$};
\draw[black,line width=0.8pt] (0,4.85)--(0.6,4.85);\node[anchor=west] at (0.8,4.85) {$y=\log_2 x$};
\draw[black,line width=0.8pt,dashed] (0,4.35)--(0.6,4.35);\node[anchor=west] at (0.8,4.35) {$y=\log_2 x+1$};
\draw[black,line width=0.8pt,dash dot] (0,3.85)--(0.6,3.85);\node[anchor=west] at (0.8,3.85) {$y=\log_2 x-1$};
\end{tikzpicture}

